CREATE TYPE "EmploymentStatus" AS ENUM ('PENDING','ACTIVE','LEAVE','TERMINATED','ARCHIVED');
CREATE TYPE "EmploymentType" AS ENUM ('FULL_TIME','PART_TIME','TEMPORARY','CONTRACTOR','VOLUNTEER','OTHER');
CREATE TYPE "ServiceEventType" AS ENUM ('HIRED','FIRST_DIRECT_CONTACT','FIRST_SUPERVISED_DIRECT_CONTACT','FIRST_UNSUPERVISED_DIRECT_CONTACT','ROLE_CHANGED','MEDICATION_DUTY_ASSIGNED');
CREATE TABLE "Employee" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"userId" TEXT,"employeeNumber" TEXT,"firstName" TEXT NOT NULL,"middleName" TEXT,"lastName" TEXT NOT NULL,"preferredName" TEXT,"email" TEXT,"phone" TEXT,"hireDate" DATE,"terminationDate" DATE,"employmentStatus" "EmploymentStatus" NOT NULL DEFAULT 'PENDING',"jobTitle" TEXT,"employmentType" "EmploymentType","createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "EmployeeRole" ("id" TEXT PRIMARY KEY,"employeeId" TEXT NOT NULL,"roleDefinitionId" TEXT NOT NULL,"effectiveFrom" DATE NOT NULL,"effectiveUntil" DATE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY ("roleDefinitionId") REFERENCES "RoleDefinition"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "DutyDefinition" ("id" TEXT PRIMARY KEY,"code" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "EmployeeDuty" ("id" TEXT PRIMARY KEY,"employeeId" TEXT NOT NULL,"dutyDefinitionId" TEXT NOT NULL,"effectiveFrom" DATE NOT NULL,"effectiveUntil" DATE,"source" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY ("dutyDefinitionId") REFERENCES "DutyDefinition"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "EmployeeServiceEvent" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"employeeId" TEXT NOT NULL,"eventType" "ServiceEventType" NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL,"programId" TEXT,"locationId" TEXT,"recordedByUserId" TEXT,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY ("programId") REFERENCES "Program"("id") ON DELETE SET NULL ON UPDATE CASCADE,FOREIGN KEY ("locationId") REFERENCES "Location"("id") ON DELETE SET NULL ON UPDATE CASCADE,FOREIGN KEY ("recordedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "Employee_organizationId_employmentStatus_idx" ON "Employee"("organizationId","employmentStatus"); CREATE INDEX "Employee_organizationId_lastName_firstName_idx" ON "Employee"("organizationId","lastName","firstName"); CREATE UNIQUE INDEX "Employee_organizationId_employeeNumber_key" ON "Employee"("organizationId","employeeNumber"); CREATE UNIQUE INDEX "Employee_organizationId_userId_key" ON "Employee"("organizationId","userId");
CREATE INDEX "EmployeeRole_employeeId_effectiveUntil_idx" ON "EmployeeRole"("employeeId","effectiveUntil"); CREATE INDEX "EmployeeDuty_employeeId_effectiveUntil_idx" ON "EmployeeDuty"("employeeId","effectiveUntil"); CREATE UNIQUE INDEX "EmployeeDuty_employeeId_dutyDefinitionId_effectiveFrom_key" ON "EmployeeDuty"("employeeId","dutyDefinitionId","effectiveFrom"); CREATE INDEX "EmployeeServiceEvent_organizationId_employeeId_occurredAt_idx" ON "EmployeeServiceEvent"("organizationId","employeeId","occurredAt");
